                            CL_CHECK(clSetKernelArg(dk, aidx++, sizeof(int),    &moe_ragged_q5));
                            const int has_min_q5 = 1;
                            CL_CHECK(clSetKernelArg(dk, aidx++, sizeof(int),    &has_min_q5));

